{
    ensure_thread_info();
    if (!pHkSession_dtor)
        throw std::runtime_error("Missing Physics export: ??1HkSession@@QEAA@XZ");
    {
        std::lock_guard<std::mutex> lock(contact_mutex);
        for (auto route = contact_routes.begin(); route != contact_routes.end();) {
            if (route->second.session == instance)
                route = contact_routes.erase(route);
            else
                ++route;
        }
        contact_callbacks.erase(instance);
    }
    pHkSession_dtor(instance);
}

